(() => {
'use strict';
const C=window.QuizCore,bank=window.QUESTION_BANK,byId=new Map(bank.map(q=>[q.id,q]));
// Keep the original storage key so an existing GitHub Pages update preserves progress.
const KEY='math-practice-214-v1',ids=bank.map(q=>q.id),counts=Object.fromEntries(Object.keys(C.TYPES).map(t=>[t,bank.filter(q=>q.type===t).length]));
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.blankState(),storageWarning='',toastTimer,modalFocus;
try{const raw=localStorage.getItem(KEY);if(raw){const p=JSON.parse(raw);state=C.importState(p,ids);state.active=C.restoreSession(p.active,ids);}}catch(e){storageWarning='暂时无法读取学习记录。可以继续练习，并在“我的记录”导出备份。';}
const ui={view:'home',filter:{type:'',number:'',year:'',region:'',source:'',search:''},bankTab:'all',limit:50,paperRegion:'',lastSession:null,zoom:100,solutionOpen:{}};
const stats=()=>C.summary(state,bank),rec=id=>state.records[id]||{},active=()=>state.active,current=()=>byId.get(active()?.ids[active()?.index]);
const isChoice=q=>['single','multi'].includes(q.type),typeName=q=>C.TYPES[q.type],key=q=>state.overrides[q.id]?.answer||q.answer||[],keyText=q=>state.overrides[q.id]?.answerText||q.answerText||'';
const known=q=>isChoice(q)?!!key(q).length:!!keyText(q)||!!q.solutionImages?.length,typeTag=q=>`<span class="tag ${q.type}">${typeName(q)}</span>`;
const sources=()=>[...new Map(bank.map(q=>[q.sourceId,q])).values()];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageWarning='当前浏览器未能保存进度，请在“我的记录”导出学习备份。';toast(storageWarning);}}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300);}
function shell(content){const s=stats(),nav=[['home','⌂','今日练习'],['papers','▥','整套试卷'],['bank','▤','分类题库'],['wrong','↺','错题本'],['my','◷','我的记录']];return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-act="nav" data-view="home" aria-label="数学刷题本首页"><span class="brand-icon">∑</span><span><strong>数学刷题本</strong><small>每天一点进步</small></span></button><nav class="nav" aria-label="主要导航">${nav.map(([v,i,t])=>`<button data-act="nav" data-view="${v}" class="${ui.view===v?'active':''}" ${ui.view===v?'aria-current="page"':''}><span class="ico" aria-hidden="true">${i}</span><span>${t}</span>${v==='wrong'&&s.wrong?`<span class="badge">${s.wrong}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><strong>把每一道题，变成自己的。</strong>${sources().length} 套完整试卷 · ${bank.length} 道题<br>进度保存在当前浏览器</div></aside><main class="main ${ui.view==='quiz'?'quiz-main':''}" id="main-content"><div class="mobile-brand"><span class="brand-icon">∑</span>数学刷题本 <span class="version-badge">全题型版</span></div>${content}<footer class="footer">原卷题面、题号和来源完整保留。答案已对照所提供的解析版核对，题内可查看原解析。<br>简答题附完整参考解答，支持保存过程与自评；自评不计入选择题正确率。</footer></main></div>`;}
function head(title,sub,small='每天一点进步'){return `<div class="topbar"><div><div class="eyebrow">${small}</div><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div><span class="date">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'})}</span></div>`;}
function statsCards(s){return `<div class="grid stats"><div class="card stat"><div class="label"><span class="dot"></span>已练题目</div><div class="num">${s.practiced}<small>/ ${bank.length} 题</small></div></div><div class="card stat"><div class="label">选择题正确率</div><div class="num">${s.accuracy===null?'—':s.accuracy+'%'}<small>${s.graded?'累计作答':'开始后统计'}</small></div></div><div class="card stat"><div class="label">待巩固题目</div><div class="num">${s.wrong}<small>题</small></div></div><div class="card stat"><div class="label">连续记对两次</div><div class="num">${s.mastered}<small>题</small></div></div></div>`;}
function numberPracticePanel(){const essays=bank.filter(q=>q.type==='essay'),numbers=[...new Set(essays.map(q=>q.number))].sort((a,b)=>a-b),selected=ui.view==='bank'&&ui.filter.type==='essay'?String(ui.filter.number||''):'';return `<section class="card number-practice" aria-labelledby="number-practice-title"><div class="number-practice-head"><div><div class="eyebrow">跨卷专项</div><h2 id="number-practice-title">按原题号练简答</h2><p class="tiny">选一个题号，把各套卷的这道简答题集中练。</p></div><button class="link-btn" data-act="number-bank" data-number="">全部简答 ${essays.length} 题 →</button></div><div class="essay-numbers" role="group" aria-label="选择简答题的原卷题号">${numbers.map(n=>{const count=new Set(essays.filter(q=>q.number===n).map(q=>q.sourceId)).size;return `<button data-act="number-bank" data-number="${n}" aria-pressed="${selected===String(n)}" class="${selected===String(n)?'active':''}"><strong>第 ${n} 题</strong><small>${count} 套</small></button>`;}).join('')}</div><p class="tiny number-practice-note">按原卷题号汇总，只收录该题号为简答题的试卷。选好题号后，可继续按年份或卷别筛选。</p></section>`;}
function openNumberBank(number){ui.filter={type:'essay',number:number?String(number):'',year:'',region:'',source:'',search:''};ui.bankTab='all';ui.limit=50;navigate('bank');}
function practiceLabel(){return ui.view==='wrong'?'错题巩固':ui.filter.type==='essay'&&ui.filter.number?`第${Number(ui.filter.number)}题专项`:'分类练习';}
function sourceCards(list){return `<div class="grid source-grid">${list.map(q=>{const qs=bank.filter(x=>x.sourceId===q.sourceId),n=qs.filter(x=>rec(x.id).attempts).length;return `<button class="card source-card" data-act="source" data-id="${q.sourceId}"><div class="source-top"><span>${q.year} · ${q.region}</span><span class="tag">完整 ${qs.length} 题</span></div><h3>${esc(q.source)}</h3><p class="paper-types">${Object.entries(C.TYPES).map(([t,label])=>{const c=qs.filter(x=>x.type===t).length;return c?`${label.replace('题','')} ${c}`:'';}).filter(Boolean).join(' · ')}</p><div class="tiny">已练 ${n} / ${qs.length} 题 <span style="float:right">进入整卷 →</span></div><div class="progress"><i style="width:${n/qs.length*100}%"></i></div></button>`;}).join('')}</div>`;}
function home(){const s=stats(),g=state.settings.goal,p=Math.min(100,Math.round(s.today/g*100));return head('把数学，练熟一点。','从选择到完整解题，20套试卷都在这里。')+`${active()?`<div class="banner" style="margin:0 0 20px"><div><p>继续上次的${active().label||'练习'}</p><small>已完成 ${Object.keys(active().results).length} / ${active().ids.length} 题 · 第 ${active().index+1} 题</small></div><button class="secondary" data-act="resume">继续练习 →</button></div>`:''}<div class="grid home-top"><section class="card hero"><span class="pill">● &nbsp; 20套原卷 · 四类题型</span><h2>每天练一点，<br>把思路记得更牢。</h2><p class="sub">${counts.single} 道单选 · ${counts.multi} 道多选<br>${counts.fill} 道填空 · ${counts.essay} 道简答</p><button class="primary" data-act="daily">开始今日练习 →</button></section><section class="card goal-card"><div class="goal-head"><h3>今日小目标</h3><button class="link-btn" data-act="nav" data-view="my">调整目标</button></div><div class="goal-num">${s.today}<span> / ${g} 题</span></div><div class="progress" role="progressbar" aria-label="今日练习目标" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p}%"></i></div><div class="goal-caption"><span class="tiny">${s.today>=g?'目标已完成，保持自己的节奏。':'再练 '+(g-s.today)+' 题，积累一点新进步。'}</span><span class="tiny">${p}%</span></div><label class="daily-type">今日练习范围<select id="daily-type">${[['','全部题型'],...Object.entries(C.TYPES)].map(([t,n])=>`<option value="${t}" ${state.settings.dailyType===t?'selected':''}>${n}</option>`).join('')}</select></label></section></div>${statsCards(s)}<div class="section-head"><h2>按题型，专练一类</h2><button class="link-btn" data-act="all-bank">查看全部 ${bank.length} 题 →</button></div><div class="grid type-cards">${[['single','A','单选题','选一项，立即核对'],['multi','AB','多选题','完整判断每个选项'],['fill','✎','填空题','写答案，再对照解析'],['essay','≡','简答题','写过程，留下关键思路']].map(([t,i,n,d])=>`<button class="card type-card ${t}" data-act="type-bank" data-type="${t}"><span class="type-icon">${i}</span><span><strong>${n}</strong><small>${d}</small></span><b>${counts[t]}<small>题</small></b></button>`).join('')}</div>${numberPracticePanel()}<div class="section-head"><h2>按自己的方式练</h2><span class="tiny">理解一步，再记住一步</span></div><div class="grid modes">${[['random','⤨','随机练习','打乱顺序，检验掌握'],['flash','▧','记忆卡片','先回想，再核对思路'],['wrong','↺','错题巩固',`${s.wrong} 道题，值得再想一次`],['papers','▥','整卷练习','按原卷顺序，完整练习']].map(([m,i,n,d])=>`<button class="card mode" data-act="mode" data-mode="${m}"><span class="mode-icon">${i}</span><strong>${n}</strong><span class="tiny">${d}</span></button>`).join('')}</div>${s.due?`<div class="banner"><div><p>${s.due} 道题到了复习时间</p><small>记住后按 1、3、7、14 天间隔再回看。</small></div><button class="secondary" data-act="due">去复习 →</button></div>`:''}<div class="section-head"><h2>完整试卷</h2><button class="link-btn" data-act="nav" data-view="papers">全部20套 →</button></div>${sourceCards(sources().slice(0,3))}`;}
function papers(){const list=sources().filter(q=>!ui.paperRegion||q.region===ui.paperRegion);return head('20套原卷，一套不漏。','保留全部题型、原题号与来源。选考题也会保留标注。','整套试卷')+`<div class="seg paper-regions">${['','新高考','北京','天津','全国甲乙'].map(r=>`<button data-act="paper-region" data-value="${r}" class="${ui.paperRegion===r?'active':''}">${r||'全部试卷'}</button>`).join('')}</div><p class="tiny" style="margin-bottom:18px">当前 ${list.length} 套 · ${bank.filter(q=>!ui.paperRegion||q.region===ui.paperRegion).length} 道题</p>${sourceCards(list)}`;}
function filterBar(){const f={type:'',year:'',region:'',source:'',search:'',...ui.filter};return `<form class="card filters" id="filter-form"><div class="seg type-seg" aria-label="题型筛选">${[['','全部题型'],...Object.entries(C.TYPES)].map(([t,n])=>`<button type="button" data-act="filter-type" data-value="${t}" class="${f.type===t?'active':''}" aria-pressed="${f.type===t}">${n}</button>`).join('')}</div><label class="sr-only" for="year-filter">年份</label><select id="year-filter" data-filter="year"><option value="">全部年份</option>${[...new Set(bank.map(q=>q.year))].sort().map(y=>`<option ${String(f.year)===String(y)?'selected':''}>${y}</option>`).join('')}</select><label class="sr-only" for="region-filter">卷别</label><select id="region-filter" data-filter="region"><option value="">全部卷别</option>${['新高考','北京','天津','全国甲乙'].map(r=>`<option ${f.region===r?'selected':''}>${r}</option>`).join('')}</select><label class="sr-only" for="source-filter">试卷</label><select id="source-filter" data-filter="source"><option value="">全部试卷</option>${sources().map(q=>`<option value="${q.sourceId}" ${Number(f.source)===q.sourceId?'selected':''}>${esc(q.source)}</option>`).join('')}</select><label class="sr-only" for="question-search">搜索试卷或题号</label><input id="question-search" name="search" type="search" value="${esc(f.search)}" placeholder="搜索：天津 第20题，按回车"><button class="sr-only" type="submit">搜索</button></form>`;}
function filtered(){return bank.filter(q=>C.matches(q,ui.filter)).filter(q=>ui.view==='wrong'?rec(q.id).inWrong:ui.bankTab==='favorites'?rec(q.id).favorite:ui.bankTab==='unseen'?!rec(q.id).attempts:ui.bankTab==='flagged'?rec(q.id).flagged:true);}
function rows(list){return `<div class="question-list">${list.map(q=>{const r=rec(q.id),status=r.inWrong?'待巩固':r.streak>=2?'已记熟':r.attempts?'已练习':r.draft?'有草稿':'未练习';return `<button class="qrow" data-act="open-question" data-id="${q.id}"><span class="qnumber">${String(q.number).padStart(2,'0')}</span><span class="row-main"><h3>${esc(q.source)}</h3><span class="qmeta">${typeTag(q)} &nbsp;原卷第 ${q.number} 题${q.elective?' · 选考题':''}</span></span><span class="row-status">${status}${r.favorite?'<span class="star">★</span>':''}<br><span class="qtype">${r.attempts?'练过 '+r.attempts+' 次':'开始练习 →'}</span></span></button>`;}).join('')}</div>`;}
function empty(t,d){return `<div class="card empty"><div class="empty-icon">▤</div><h2>${t}</h2><p>${d}</p><button class="primary" data-act="all-bank">查看全部题目 →</button></div>`;}
function bankView(){const wrong=ui.view==='wrong',list=filtered(),number=ui.filter.type==='essay'?Number(ui.filter.number):0,papers=new Set(list.map(q=>q.sourceId)).size;return head(wrong?'多练一次，更近一步。':number?`各卷第${number}题，集中练。`:'四类题型，按需练习。',wrong?'答错或自评“还需练习”的题会自动收集；连续记对两次后移出。':number?'按原卷题号汇总简答题，比较不同试卷的设问与解题步骤。':`${bank.length} 道原题，支持按题型、年份、卷别和试卷筛选。`,wrong?'错题与待巩固题':number?'按原题号练简答':'分类题库')+`${wrong?'':`<div class="seg bank-tabs">${[['all','全部题目'],['unseen','未练题'],['favorites','我的收藏'],['flagged','疑问题目']].map(([v,t])=>`<button data-act="bank-tab" data-value="${v}" class="${ui.bankTab===v?'active':''}">${t}</button>`).join('')}</div>`}${!wrong&&ui.filter.type==='essay'?numberPracticePanel():''}${filterBar()}<div class="bank-toolbar"><span class="tiny">${number?`第${number}题 · ${papers}套试卷 · `:'共 '}${list.length} 道${ui.filter.type?C.TYPES[ui.filter.type]:'题'}${list.length>ui.limit?' · 已显示 '+ui.limit+' 道':''}</span><div class="toolbar-buttons"><button class="secondary" data-act="clear-filter">清除筛选</button><button class="primary" data-act="filtered-practice" ${!list.length?'disabled':''}>练习这些题 →</button></div></div>${list.length?rows(list.slice(0,ui.limit)):empty(wrong?'这里暂时没有待巩固的题':'当前筛选没有题目',wrong?'先开始练习，值得重做的题会收集到这里。':'可以清除筛选，或换个试卷、题型。')}${list.length>ui.limit?`<button class="secondary show-more" data-act="show-more">再显示 ${Math.min(50,list.length-ui.limit)} 道题 ↓</button>`:''}`;}
function numberGrid(){const a=active();let previous='';return `<div class="number-grid">${a.ids.map((id,i)=>{const q=byId.get(id),r=a.results[id],cls=r?['correct','wrong'].includes(r.result)?r.result:r.result==='again'?'wrong':'done':'';let divider='';if(a.label==='整卷练习'&&q.type!==previous){divider=`<span class="number-divider">${typeName(q)}</span>`;previous=q.type;}return `${divider}<button data-act="jump" data-index="${i}" class="${cls} ${i===a.index?'current':''}" aria-label="${esc(q.source)}，原卷第 ${q.number} 题，${r?'已完成':'未完成'}" title="${esc(q.source)} · 第${q.number}题" ${i===a.index?'aria-current="step"':''}>${a.label==='整卷练习'?q.number:i+1}</button>`;}).join('')}</div><div class="legend"><span><i class="correct"></i>答对</span><span><i class="wrong"></i>待巩固</span><span><i class="done"></i>已回忆/自评</span></div>`;}
function solutionPanel(q){if(!q.solutionImages?.length)return '';const open=ui.solutionOpen[q.id]??q.type==='essay';return `<div class="source-solution"><button class="solution-toggle" data-act="solution-toggle" aria-expanded="${open}" aria-controls="solution-${q.id}"><span>${q.type==='essay'?'完整参考解答':'查看随卷答案与解析'}</span><span>${open?'收起 −':'展开 ＋'}</span></button>${open?`<div id="solution-${q.id}" class="solution-content"><p class="tiny solution-source">${esc(q.answerSourceFile)} · 第 ${q.answerSourcePages.join('、')} 页</p>${q.solutionImages.map((im,i)=>`<figure><button class="solution-image-button" data-act="solution-zoom" data-index="${i}" aria-label="放大第 ${i+1} 段解析"><img class="solution-image" src="${im.image}" width="${im.width}" height="${im.height}" loading="lazy" decoding="async" alt="${esc(q.source)}第${q.number}题参考解析，第${i+1}段，共${q.solutionImages.length}段"></button>${q.solutionImages.length>1?`<figcaption>第 ${i+1} / ${q.solutionImages.length} 段 · 原解析第 ${im.page} 页</figcaption>`:''}</figure>`).join('')}<p class="tiny">点按解析可放大查看公式与图形。</p></div>`:''}</div>`;}
function responseFeedback(q,r,{flash=false}={}){const snapshot=!!r?.at,over=snapshot?r.overridden:!!state.overrides[q.id],ans=isChoice(q)?(r?.answer||key(q)).join('、'):(snapshot?(r.answerText||''):keyText(q)),hasText=!!ans,hasSource=!!q.solutionImages?.length,has=hasText||hasSource,choice=isChoice(q),selected=r?.selected||[],draft=r?.text??active()?.drafts[q.id]??'';let title=!has?'保存过程，检查自己的思路':flash?'先回想，再核对关键一步':choice?r?.result==='correct'?'答对了，继续保持。':'这道题，值得再想一次。':q.type==='essay'?'对照参考解答，检查关键步骤':'对照参考答案，自己核对';const pending=!has,wrong=r?.result==='wrong'||r?.result==='again',changed=snapshot&&!over&&choice&&C.canonical(r.answer).join('')!==C.canonical(q.answer).join('');return `<section class="feedback ${wrong?'wrong':pending?'pending':''}" aria-live="polite"><div class="feedback-title">${title}</div>${choice&&!flash?`<div class="answer-line"><span>你的选择 <strong>${selected.join('、')||'—'}</strong></span><span>${over?'个人校正答案':snapshot?'本次判分答案':'核对答案'} <strong>${ans||'待核对'}</strong></span></div>`:hasText?`<div class="reference-answer"><span>${over?'个人校正答案':'参考答案'}</span><p>${esc(ans)}</p></div>`:''}${changed?`<p class="answer-note">本次记录按作答时的答案保留；最新核对答案为 ${q.answer.join('、')}，请对照下方解析。</p>`:''}${!choice&&draft?`<details class="submitted-response"><summary>查看本次作答</summary><div>${esc(draft)}</div></details>`:''}${q.answerNote?`<p class="answer-note">${esc(q.answerNote)}</p>`:''}${hasText&&q.explanation?`<div class="explanation">${esc(q.explanation)}</div>`:''}${solutionPanel(q)}${!has?'<p>可以先保存作答和自己的核对结果，后续再补充参考答案。</p>':''}${q.type==='fill'&&hasText&&!snapshot&&C.sameWriting(draft,[ans,...q.acceptedAnswers])?'<p class="same-writing">✓ 你的输入与一种参考写法一致，仍请核对各空顺序与条件。</p>':''}<p class="answer-disclaimer">${over?'当前使用个人校正答案；随卷原解析供对照。':hasSource?'已对照你提供的解析版核对；原解析完整保留。':''}${choice&&q.type==='multi'?' 多选需完整选对，少选、多选或错选均记为未答对。':!choice?' 填空、简答和记忆卡片按你的自评记录，不计入选择题正确率。':''}</p><div class="feedback-links"><button class="link-btn" data-act="correct-answer">${q.type==='essay'?'补充参考思路':'校正答案'}</button><button class="link-btn" data-act="flag">${rec(q.id).flagged?'取消疑问标记':'标记疑问'}</button><button class="link-btn" data-act="wrong-toggle">${rec(q.id).inWrong?'移出错题':'加入错题'}</button></div></section>`;}
function freeInput(q,a,r){const text=r?.text??a.drafts[q.id]??'',last=rec(q.id).draft||'';return `<section class="free-response"><div class="response-label"><label for="free-answer">${q.type==='fill'?'填写你的答案':'写下解题过程或关键步骤'}</label><span class="save-status">${r?'已记录':'输入后自动保存'}</span></div><textarea id="free-answer" class="${q.type==='essay'?'essay-draft':'fill-draft'}" maxlength="12000" ${r?'readonly':''} placeholder="${q.type==='fill'?'按题目顺序填写；多个空可分行，例如：\n第一空：…\n第二空：…':'可以按（1）（2）（3）分步写。\n也可以先在草稿纸上完成，再点击“已在纸上作答”。'}">${esc(text)}</textarea>${!r?`<div class="math-keys" aria-label="常用数学符号">${['π','√','∞','±','≤','≥','∈','∪','²','/'].map(s=>`<button data-act="math-symbol" data-symbol="${s}" aria-label="插入 ${s}">${s}</button>`).join('')}</div>`:''}${!r&&last&&last!==text?`<details class="previous-response"><summary>查看之前保存的作答</summary><div>${esc(last)}</div><button class="link-btn" data-act="restore-draft">继续编辑这份作答</button></details>`:''}</section>`;}
function assessment(q){return `<div class="self-review"><p>这道题，你掌握得怎么样？</p><div><button class="secondary" data-act="self-review" data-result="again">还需练习 ↺</button><button class="primary" data-act="self-review" data-result="remembered">${q.type==='essay'?'已完成，思路清楚':'核对无误，记住了'} ✓</button></div></div>`;}
function quiz(){const a=active();if(!a){ui.view='home';return home();}const q=current(),r=a.results[q.id],pick=a.picks[q.id]||[],flash=a.mode==='flash',reveal=!!(a.revealed[q.id]||r),choice=isChoice(q),done=Object.keys(a.results).length;return `<div class="quiz-top"><button class="back" data-act="${/^第\d+题专项$/.test(a.label)?'number-return':'nav'}" data-view="${a.label==='整卷练习'?'papers':'home'}">← ${a.label==='整卷练习'?'返回试卷列表':/^第\d+题专项$/.test(a.label)?'返回题号列表':'返回首页'}</button><div class="tools"><span class="tiny" id="session-timer">00:00</span><button class="round-btn ${rec(q.id).favorite?'on':''}" data-act="favorite" aria-label="${rec(q.id).favorite?'取消收藏':'收藏题目'}" aria-pressed="${!!rec(q.id).favorite}">${rec(q.id).favorite?'★':'☆'}</button><button class="round-btn" data-act="drawer" aria-label="打开答题卡">▦</button><button class="round-btn" data-act="end-session" aria-label="结束本次练习">⋯</button></div></div><div class="quiz-layout"><article class="card question-card"><div class="question-head"><div class="question-labels">${typeTag(q)}<span class="tiny">${flash?'记忆卡片':a.label||'自主练习'}${q.elective?' · 选考题':''}</span></div><span class="q-position"><strong>${a.index+1}</strong> / ${a.ids.length}</span></div><div class="question-source">${esc(q.source)} · 原卷第 ${q.number} 题 · PDF 第 ${q.sourcePages.join('、')} 页</div><figure class="question-figure"><img class="question-image" src="${q.image}" width="${q.width}" height="${q.height}" alt="${esc(q.source)}第${q.number}题完整题面，点击可放大" data-act="zoom" decoding="async"></figure><button class="zoom-hint" data-act="zoom">⌕ 放大题面，查看公式与配图</button>${flash?`${reveal?responseFeedback(q,r,{flash:true}):'<p class="recall-prompt">先自己回想答案和解题步骤，再展开核对。</p>'}${!reveal?'<button class="primary reveal-button" data-act="reveal">回想好了，展开核对</button>':!r?assessment(q):''}`:choice?`<div class="option-grid" role="group" aria-label="${typeName(q)}，请选择答案">${C.LETTERS.map(l=>{let cls=pick.includes(l)?'selected':'';if(r){if(r.answer.includes(l))cls='correct';else if(r.selected.includes(l))cls='wrong';}return `<button class="option ${cls}" data-act="pick" data-letter="${l}" aria-pressed="${pick.includes(l)}" ${r?'disabled':''}>${l}${r&&r.answer.includes(l)?' ✓':r&&r.selected.includes(l)?' ×':''}</button>`;}).join('')}</div><p class="selection-hint">${q.type==='multi'?'可选择多个选项，选好后确认。':'请选择一个选项。'}答案选项见上方原题。</p>${r?responseFeedback(q,r):''}`:`${freeInput(q,a,r)}${reveal?responseFeedback(q,r):''}${reveal&&!r?assessment(q):''}`}<div class="quiz-actions"><div><button class="secondary" data-act="previous" ${a.index===0?'disabled':''}>上一题</button>${!r?'<button class="secondary" data-act="next">暂时跳过</button>':''}</div>${r?`<button class="primary" data-act="next">${a.index===a.ids.length-1?'完成练习':'下一题 →'}</button>`:!flash&&choice?`<button class="primary" data-act="submit" ${!pick.length?'disabled':''}>确认答案</button>`:!flash&&!reveal?`<div class="free-submit-buttons"><button class="secondary" data-act="paper-response">已在纸上作答</button><button class="primary" data-act="submit-free">${q.type==='fill'?'保存并核对':'保存并核对解析'}</button></div>`:''}</div><details class="note-area" ${rec(q.id).notes?'open':''}><summary>✎ 我的解题笔记${rec(q.id).notes?' · 已保存':''}</summary><label class="sr-only" for="question-notes">解题笔记</label><textarea id="question-notes" maxlength="12000" placeholder="记下关键条件、容易忘的一步，或者自己的记忆提示。">${esc(rec(q.id).notes||'')}</textarea><span class="tiny">自动保存到当前浏览器。</span></details></article><aside class="quiz-side"><section class="card side-card"><h3>${esc(a.label||'本次练习')}</h3><div class="progress"><i style="width:${done/a.ids.length*100}%"></i></div><div class="side-meta"><span>已完成 ${done} 题</span><span>共 ${a.ids.length} 题</span></div>${numberGrid()}<div class="side-tip">${flash?'先回忆，再查看。答案之外，更要记住关键思路。':choice?'选择题提交后自动核对；错题会自动收集。':'填空、简答先作答，再对照随卷解析检查步骤并自评。'}<br><br>自评与回忆不计入选择题正确率。<br><br><span class="kbd">1–4</span> 选择选项<br><span class="kbd">Enter</span> 确认 / 下一题</div></section></aside></div>`;}
function my(){const s=stats(),days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const k=C.dateKey(d);return {label:i===6?'今天':(d.getMonth()+1)+'/'+d.getDate(),count:state.history.filter(h=>C.dateKey(h.at)===k).length};}),max=Math.max(...days.map(x=>x.count),state.settings.goal,1);return head('每一点进步，都算数。','练习设置、收藏、笔记与学习备份，都在这里。','我的学习记录')+statsCards(s)+`<div class="grid my-grid" style="margin-top:22px"><section class="card"><div class="section-head" style="margin:0"><h2>最近七天</h2><span class="tiny">作答与自评次数</span></div><div class="week">${days.map((d,i)=>`<div class="day-bar ${i===6?'today':''}"><em>${d.count}</em><i style="height:${Math.max(3,d.count/max*90)}px"></i><span>${d.label}</span></div>`).join('')}</div><div class="banner"><div><p>给记忆一点合适的间隔</p><small>${s.due} 道题已到复习时间 · 累计自评/回忆 ${s.selfReviewed} 次</small></div><button class="secondary" data-act="due" ${s.due?'':'disabled'}>去回顾</button></div><div class="backup-btns"><button class="secondary" data-act="favorites">★ 收藏 ${s.favorites}</button><button class="secondary" data-act="flagged">? 疑问题目 ${bank.filter(q=>rec(q.id).flagged).length}</button></div></section><section class="card"><h2>练习设置</h2><div class="settings-row"><div><strong>每日目标</strong><p class="tiny">根据题目难度安排适合自己的量</p></div><select id="goal-setting" aria-label="每日目标题数">${[5,10,20,30,50].map(n=>`<option value="${n}" ${n===state.settings.goal?'selected':''}>${n} 题</option>`).join('')}</select></div><div class="settings-row"><div><strong>单选题选中即提交</strong><p class="tiny">多选仍需手动确认</p></div><input class="toggle" id="auto-setting" type="checkbox" aria-label="单选题选中即提交" ${state.settings.autoSubmit?'checked':''}></div><div class="settings-row"><div><strong>错题自动巩固</strong><p class="tiny">连续答对或自评记住两次后移出</p></div><span class="tag">已开启</span></div></section><section class="card"><h2>学习备份</h2><p class="tiny" style="margin-top:10px">进度、收藏、草稿、笔记和校正答案保存在当前浏览器。换设备或清理浏览器前请导出备份，再在新设备导入。旧版选择题备份也可以导入。</p>${storageWarning?`<p class="storage-warning">${esc(storageWarning)}</p>`:''}<div class="backup-btns"><button class="primary" data-act="export">导出学习备份 ↓</button><button class="secondary" data-act="import">导入备份 ↑</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><button class="link-btn reset-link" data-act="reset">清空学习记录</button></section><section class="card"><h2>这次升级了什么</h2><ul class="info-list"><li>新增按原题号练简答：一键汇总各卷第17题等，可继续按年份、卷别筛选。</li><li>20套完整试卷，共 ${bank.length} 题，含全部填空和简答。</li><li>选择、填空共300题已逐题对照所提供的解析版核对。</li><li>填空题可写答案、核对参考解析后自评。</li><li>简答题可保存解题过程，也可在草稿纸上完成。</li><li>112道简答题新增随卷完整参考解答，支持点按放大。</li><li>解析按需展开加载，首页不会下载整套解析图片。</li><li>同一网址与浏览器下，升级会保留原版选择题记录。</li></ul></section></div>`;}
function results(){const a=ui.lastSession;if(!a)return home();const list=Object.values(a.results),correct=list.filter(x=>x.result==='correct').length,wrong=list.filter(x=>x.result==='wrong').length,self=list.filter(x=>['remembered','again'].includes(x.result)).length,again=list.filter(x=>['wrong','again'].includes(x.result)).length,skip=a.ids.length-list.length;return `<div class="card result-card"><div class="result-icon">✓</div><div class="eyebrow">练习已记录</div><h1>又向前走了一小步。</h1><p class="sub">完成 ${list.length} / ${a.ids.length} 题${skip?' · 跳过 '+skip+' 题':''}</p><div class="result-stats"><div><strong>${correct}</strong><span>选择题答对</span></div><div><strong>${self}</strong><span>已自评 / 回忆</span></div><div><strong>${again}</strong><span>需要再练</span></div></div><p class="tiny">本次选择题正确率：${correct+wrong?Math.round(correct/(correct+wrong)*100)+'%':'暂无选择题判分'} · 自评不计入正确率</p><div class="review-note">${again?'本次需要巩固的题已收入错题本。回想最关键的一步，再试一次。':'完成后回想一下：这道题为什么这样做？把关键一步写进笔记。'}<br>连续答对或自评记住两次后，题目会自动移出错题本。</div><div class="result-actions">${again?'<button class="primary" data-act="retry-wrong">再练本次待巩固题</button>':''}<button class="secondary" data-act="restart">再练一遍</button><button class="secondary" data-act="nav" data-view="home">返回首页</button></div></div>`;}
function render(scroll=false){const content=ui.view==='home'?home():ui.view==='papers'?papers():['bank','wrong'].includes(ui.view)?bankView():ui.view==='quiz'?quiz():ui.view==='my'?my():results();$('#app').innerHTML=shell(content);if(scroll)window.scrollTo({top:0,behavior:'instant'});tick();}
function navigate(view){closeModal();if(view==='wrong'&&ui.view!=='wrong'){ui.filter={};ui.limit=50;}ui.view=view;render(true);}
function start(qids,mode='quiz',label='自主练习'){const deck=[...new Set(qids)].filter(id=>byId.has(id));if(!deck.length){toast('当前没有可练习的题目');return;}state.active={ids:deck,index:0,mode,label,results:{},picks:{},drafts:{},revealed:{},startedAt:Date.now(),questionStartedAt:Date.now()};persist();navigate('quiz');}
function daily(){const pool=bank.filter(q=>!state.settings.dailyType||q.type===state.settings.dailyType),now=Date.now(),due=pool.filter(q=>rec(q.id).due&&rec(q.id).due<=now).sort((a,b)=>Number(rec(b.id).inWrong)-Number(rec(a.id).inWrong)),unseen=C.shuffle(pool.filter(q=>!rec(q.id).attempts)),rest=C.shuffle(pool.filter(q=>rec(q.id).attempts&&!due.includes(q)));start([...due,...unseen,...rest].slice(0,state.settings.goal).map(q=>q.id),'quiz','今日练习');}
function pick(letter){const a=active(),q=current();if(!a||!q||!isChoice(q)||a.results[q.id]||a.mode==='flash')return;const p=a.picks[q.id]||[];a.picks[q.id]=q.type==='single'?[letter]:C.canonical(p.includes(letter)?p.filter(l=>l!==letter):[...p,letter]);persist();if(q.type==='single'&&state.settings.autoSubmit)submit();else render();}
function record(result){const a=active(),q=current();if(!a||a.results[q.id])return;const now=Date.now(),text=a.drafts[q.id]||'',r={result,selected:C.canonical(a.picks[q.id]),answer:C.canonical(key(q)),answerText:keyText(q),text,overridden:!!state.overrides[q.id],at:now,seconds:Math.max(0,Math.round((now-a.questionStartedAt)/1000))};a.results[q.id]=r;state.records[q.id]={...C.advance(rec(q.id),result,now),lastSelection:r.selected,...(text?{draft:text}:{})};state.history.push({id:q.id,...r,text:text.slice(0,2000)});state.history=state.history.slice(-5000);persist();render();}
function submit(){const q=current(),a=active();if(!q||!isChoice(q))return;const p=a.picks[q.id]||[];if(!p.length){toast('请先选择答案');return;}const result=C.grade(p,key(q),q.type);record(result===null?'ungraded':result?'correct':'wrong');}
function revealFree(onPaper=false){const a=active(),q=current();if(!onPaper&&!a.drafts[q.id]?.trim()){toast('可以先写下作答，或选择“已在纸上作答”');$('#free-answer')?.focus();return;}a.revealed[q.id]=true;if(a.drafts[q.id])state.records[q.id]={...rec(q.id),draft:a.drafts[q.id]};persist();render();}
function move(i){const a=active();if(i>=a.ids.length){finish();return;}a.index=Math.max(0,i);a.questionStartedAt=Date.now();persist();closeModal();render(true);}
function finish(){ui.lastSession=active();state.active=null;persist();navigate('result');}
function modal(content,cls=''){modalFocus=document.activeElement;$('#app').inert=true;$('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay-root button,#overlay-root input,#overlay-root textarea')?.focus(),0);}
function closeModal(){if(!$('#overlay-root').innerHTML)return;$('#overlay-root').innerHTML='';$('#app').inert=false;document.body.style.overflow='';modalFocus?.focus?.();}
function dialog(title,content,buttons){modal(`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="round-btn" data-act="close-modal" aria-label="关闭弹窗">×</button></div>${content}<div class="modal-actions">${buttons}</div>`);}
function correction(){const q=current();dialog(q.type==='essay'?'补充自己的参考思路':'校正这道题的答案',`<p>${esc(q.source)} · 第 ${q.number} 题</p><p style="margin-top:10px">${isChoice(q)?q.type==='single'?'请选择一个答案。':'请选择全部正确选项。':'填入核对后的答案或参考步骤。'}仅保存在当前浏览器，下次练习时生效；原有记录保留。</p>${isChoice(q)?`<div class="correction-options">${C.LETTERS.map(l=>`<label><input name="answer-correction" type="${q.type==='single'?'radio':'checkbox'}" value="${l}" ${key(q).includes(l)?'checked':''}>${l}</label>`).join('')}</div>`:`<textarea id="text-correction" maxlength="4000" aria-label="个人参考答案">${esc(keyText(q))}</textarea>`}`,`<button class="secondary" data-act="restore-answer">恢复原参考内容</button><button class="primary" data-act="save-answer">保存</button>`);}
function zoom(solutionIndex=null){const q=current(),im=solutionIndex===null?{image:q.image}:q.solutionImages[solutionIndex];if(!im)return;ui.zoom=100;modal(`<div class="modal-head"><h2 id="modal-title">${esc(q.source)} · 第 ${q.number} 题</h2><button class="round-btn" data-act="close-modal" aria-label="关闭放大图片">×</button></div><div class="zoom-controls"><span>左右滑动查看完整图片</span><div><button data-act="zoom-out" aria-label="缩小题面">−</button><b id="zoom-label">100%</b><button data-act="zoom-in" aria-label="放大题面">＋</button></div></div><div class="zoom-body"><img id="zoom-image" style="width:1000px" src="${im.image}" alt="${solutionIndex===null?'完整原题':'参考解析'}放大图"></div>`,'zoom');}
function exportBackup(){const data={...state,active:null,exportedAt:new Date().toISOString(),questionBank:'all-412-v2'},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='数学刷题本_学习备份_'+C.dateKey(Date.now())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习备份已导出');}
async function importBackup(file){if(!file)return;if(file.size>16e6){toast('备份文件过大，请选择正确的学习备份');return;}try{ui.pendingImport=C.importState(JSON.parse(await file.text()),ids);dialog('导入学习备份',`<p>备份中包含 ${Object.keys(ui.pendingImport.records).length} 道题的记录。导入会替换当前浏览器中的进度、草稿、收藏和笔记。可以先导出当前备份。</p>`,`<button class="secondary" data-act="close-modal">取消</button><button class="primary" data-act="confirm-import">确认导入</button>`);}catch(e){toast('无法读取，请选择本网页导出的 JSON 学习备份');}}
function tick(){const t=$('#session-timer');if(!t||!active())return;const n=Math.max(0,Math.floor((Date.now()-active().startedAt)/1000));t.textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function setFilter(){ui.limit=50;render();}
function allBank(type=''){ui.filter={type,number:'',year:'',region:'',source:'',search:''};ui.bankTab='all';ui.limit=50;navigate('bank');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=active(),q=current();switch(b.dataset.act){
case'nav':navigate(b.dataset.view);break;case'all-bank':allBank();break;case'type-bank':allBank(b.dataset.type);break;case'number-bank':openNumberBank(b.dataset.number);break;case'number-return':{const n=Number(a.label.match(/^第(\d+)题专项$/)?.[1]);if(ui.filter.type==='essay'&&Number(ui.filter.number)===n)navigate('bank');else openNumberBank(n);break;}case'resume':navigate('quiz');break;case'daily':daily();break;
case'mode':{const m=b.dataset.mode;if(['papers','wrong'].includes(m)){navigate(m);break;}const pool=bank.filter(x=>!state.settings.dailyType||x.type===state.settings.dailyType),due=C.shuffle(pool.filter(x=>rec(x.id).inWrong||rec(x.id).due<=Date.now()));const deck=m==='flash'?[...new Set([...due,...C.shuffle(pool)].map(x=>x.id))]:C.shuffle(pool).map(x=>x.id);start(deck.slice(0,state.settings.goal),m==='flash'?'flash':'quiz',m==='flash'?'记忆卡片':'随机练习');break;}
case'due':start(C.shuffle(bank.filter(x=>rec(x.id).due&&rec(x.id).due<=Date.now())).map(x=>x.id),'quiz','间隔复习');break;case'source':start(bank.filter(x=>x.sourceId===Number(b.dataset.id)).map(x=>x.id),'quiz','整卷练习');break;case'paper-region':ui.paperRegion=b.dataset.value;render();break;
case'filter-type':ui.filter.type=b.dataset.value;if(b.dataset.value!=='essay')ui.filter.number='';setFilter();break;case'bank-tab':ui.bankTab=b.dataset.value;setFilter();break;case'clear-filter':ui.filter={};setFilter();break;case'show-more':ui.limit+=50;render();break;case'filtered-practice':start(filtered().map(x=>x.id),'quiz',practiceLabel());break;case'open-question':{const list=filtered().map(x=>x.id);start(list,'quiz',practiceLabel());move(list.indexOf(b.dataset.id));break;}
case'pick':pick(b.dataset.letter);break;case'submit':submit();break;case'previous':move(a.index-1);break;case'next':move(a.index+1);break;case'jump':move(Number(b.dataset.index));break;case'reveal':a.revealed[q.id]=true;persist();render();break;case'submit-free':revealFree();break;case'paper-response':revealFree(true);break;case'self-review':record(b.dataset.result);break;
case'math-symbol':{const t=$('#free-answer');if(!t||t.readOnly)break;const start=t.selectionStart,end=t.selectionEnd;t.value=t.value.slice(0,start)+b.dataset.symbol+t.value.slice(end);t.focus();t.setSelectionRange(start+b.dataset.symbol.length,start+b.dataset.symbol.length);a.drafts[q.id]=t.value;state.records[q.id]={...rec(q.id),draft:t.value};persist();break;}
case'restore-draft':a.drafts[q.id]=rec(q.id).draft;persist();render();break;case'favorite':state.records[q.id]={...rec(q.id),favorite:!rec(q.id).favorite};persist();render();toast(rec(q.id).favorite?'已加入收藏':'已取消收藏');break;case'wrong-toggle':state.records[q.id]={...rec(q.id),inWrong:!rec(q.id).inWrong};persist();render();toast(rec(q.id).inWrong?'已加入错题本':'已移出错题本');break;case'flag':state.records[q.id]={...rec(q.id),flagged:!rec(q.id).flagged};persist();render();toast(rec(q.id).flagged?'已标记疑问':'已取消疑问标记');break;
case'solution-toggle':ui.solutionOpen[q.id]=!(ui.solutionOpen[q.id]??q.type==='essay');render();break;case'solution-zoom':zoom(Number(b.dataset.index));break;case'zoom':zoom();break;case'zoom-in':case'zoom-out':ui.zoom=Math.min(200,Math.max(50,ui.zoom+(b.dataset.act==='zoom-in'?25:-25)));$('#zoom-image').style.width=(ui.zoom*10)+'px';$('#zoom-label').textContent=ui.zoom+'%';break;case'drawer':dialog('本次答题卡',numberGrid(),'<button class="secondary" data-act="close-modal">继续练习</button>');break;case'end-session':dialog('结束本次练习？','<p>已经提交的答案、草稿、错题和笔记都会保留。也可以返回首页，下次继续本次练习。</p>','<button class="secondary" data-act="close-modal">继续练习</button><button class="primary" data-act="finish">结束并查看结果</button>');break;case'finish':finish();break;case'close-modal':closeModal();break;
case'correct-answer':correction();break;case'save-answer':{if(isChoice(q)){const chosen=[...document.querySelectorAll('[name="answer-correction"]:checked')].map(x=>x.value);if(!chosen.length){toast('请至少选择一个答案');break;}state.overrides[q.id]={answer:C.canonical(chosen),at:Date.now()};}else{const text=$('#text-correction').value.trim();if(!text){toast('请填写参考内容');break;}state.overrides[q.id]={answerText:text,at:Date.now()};}persist();closeModal();render();toast('已保存，下次练习时生效');break;}case'restore-answer':delete state.overrides[q.id];persist();closeModal();render();toast('已恢复原参考内容');break;
case'favorites':ui.bankTab='favorites';ui.filter={};ui.limit=50;navigate('bank');break;case'flagged':ui.bankTab='flagged';ui.filter={};ui.limit=50;navigate('bank');break;case'export':exportBackup();break;case'import':$('#import-file').click();break;case'confirm-import':state=ui.pendingImport;delete ui.pendingImport;persist();closeModal();render();toast('学习备份已导入');break;case'reset':dialog('清空学习记录？','<p>这会清空当前浏览器的进度、草稿、错题、收藏、笔记和个人参考答案。题库会保留。建议先导出备份。</p>','<button class="secondary" data-act="close-modal">取消</button><button class="danger" data-act="confirm-reset">确认清空</button>');break;case'confirm-reset':state=C.blankState();persist();closeModal();render();toast('记录已清空');break;case'restart':start(ui.lastSession.ids,ui.lastSession.mode,ui.lastSession.label);break;case'retry-wrong':start(ui.lastSession.ids.filter(id=>['wrong','again'].includes(ui.lastSession.results[id]?.result)),ui.lastSession.mode,'再次巩固');break;
}});
document.addEventListener('input',e=>{const q=current();if(!q)return;if(e.target.id==='question-notes'){state.records[q.id]={...rec(q.id),notes:e.target.value.slice(0,12000)};persist();}if(e.target.id==='free-answer'&&!active().results[q.id]){const text=e.target.value.slice(0,12000);active().drafts[q.id]=text;state.records[q.id]={...rec(q.id),draft:text};persist();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){ui.filter[t.dataset.filter]=t.value;setFilter();}if(t.id==='goal-setting'){state.settings.goal=Number(t.value);persist();render();toast('每日目标已更新');}if(t.id==='daily-type'){state.settings.dailyType=t.value;persist();toast(t.value?'今日将练习'+C.TYPES[t.value]:'今日将练习全部题型');}if(t.id==='auto-setting'){state.settings.autoSubmit=t.checked;persist();toast(t.checked?'已开启单选即选即判':'已改为手动确认答案');}if(t.id==='import-file')importBackup(t.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='filter-form'){e.preventDefault();ui.filter.search=e.target.elements.search.value;setFilter();}});
document.addEventListener('keydown',e=>{if($('#overlay-root').innerHTML){if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...document.querySelectorAll('#overlay-root button,#overlay-root input,#overlay-root select,#overlay-root textarea')].filter(x=>!x.disabled);if(els.length){const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}return;}if(ui.view!=='quiz'||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT|BUTTON/.test(document.activeElement?.tagName))return;const a=active(),q=current();if(!a)return;if(/^[1-4]$/.test(e.key)){e.preventDefault();pick(C.LETTERS[Number(e.key)-1]);}if(e.key==='Enter'){e.preventDefault();if(a.results[q.id])move(a.index+1);else if(a.mode==='flash'){a.revealed[q.id]=true;persist();render();}else if(isChoice(q))submit();}});
$('#overlay-root').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
setInterval(tick,1000);render();if(storageWarning)toast(storageWarning);
})();
